class Solution {
public:
    vector<vector<int>> getAncestors(int n, vector<vector<int>>& edges) {
        vector<vector<int>> adj(n);
        for (auto& e : edges) {
            adj[e[0]].push_back(e[1]);
        }
        vector<vector<int>> ans(n);
        vector<int> visited(n);
        vector<int> q;
        q.reserve(n);
        for (int i = 0; i < n; i++) {
            fill(visited.begin(), visited.end(), 0);
            q.clear();
            q.push_back(i);
            visited[i] = 1;
            size_t head = 0;
            while (head < q.size()) {
                int u = q[head++];
                for (int v : adj[u]) {
                    if (!visited[v]) {
                        visited[v] = 1;
                        ans[v].push_back(i);
                        q.push_back(v);
                    }
                }
            }
        }
        return ans;
    }
};
